import { createRoute, z } from '@hono/zod-openapi'

const AccountSchema = z
  .object({
    balances: z
      .object({
        available_balance: z
          .int()
          .openapi({
            description:
              "The Account's available balance, representing the current balance less any open Pending Transactions on the Account.",
          }),
        current_balance: z
          .int()
          .openapi({
            description:
              "The Account's current balance, representing the sum of all posted Transactions on the Account.",
          }),
      })
      .openapi({
        description:
          "The Account's balances in the minor unit of its currency. For dollars, for example, these values will represent cents.",
        required: ['current_balance', 'available_balance'],
        title: 'Balances',
        'x-title-plural': 'Balancess',
      }),
    created_at: z.iso
      .datetime({ offset: true })
      .openapi({
        description:
          'The [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) time at which the Account was created.',
      }),
    currency: z
      .enum(['CAD', 'CHF', 'EUR', 'GBP', 'JPY', 'USD'])
      .openapi({
        description:
          'The [ISO 4217](https://en.wikipedia.org/wiki/ISO_4217) code for the Account currency.',
        'x-enum-descriptions': [
          'Canadian Dollar (CAD)',
          'Swiss Franc (CHF)',
          'Euro (EUR)',
          'British Pound (GBP)',
          'Japanese Yen (JPY)',
          'US Dollar (USD)',
        ],
      }),
    entity_id: z
      .string()
      .nullable()
      .openapi({ description: 'The identifier for the Entity the Account belongs to.' }),
    id: z.string().openapi({ description: 'The Account identifier.' }),
    informational_entity_id: z
      .string()
      .nullable()
      .openapi({
        description:
          'The identifier of an Entity that, while not owning the Account, is associated with its activity.',
      }),
    interest_accrued: z
      .string()
      .openapi({
        description:
          'The interest accrued but not yet paid, expressed as a string containing a floating-point value.',
      }),
    interest_accrued_at: z.iso
      .date()
      .nullable()
      .openapi({
        description:
          'The latest [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) date on which interest was accrued.',
      }),
    name: z.string().openapi({ description: 'The name you choose for the Account.' }),
    status: z
      .enum(['open', 'closed'])
      .openapi({
        description: 'The status of the Account.',
        'x-enum-descriptions': [
          'Open Accounts that are ready to use.',
          'Closed Accounts on which no new activity can occur.',
        ],
      }),
    type: z
      .literal('account')
      .openapi({
        description:
          "A constant representing the object's type. For this resource it will always be `account`.",
      }),
  })
  .openapi({
    description:
      'Accounts are your bank accounts with Increase. They store money, receive transfers, and send payments. They earn interest and have depository insurance.',
    example: {
      balances: { available_balance: 100, current_balance: 100 },
      bank: 'first_internet_bank',
      created_at: '2020-01-31T23:59:59Z',
      currency: 'USD',
      entity_id: 'entity_n8y8tnk2p9339ti393yi',
      id: 'account_in71c4amph0vgo2qllky',
      informational_entity_id: null,
      interest_accrued: '0.01',
      interest_accrued_at: '2020-01-31',
      name: 'My first account!',
      replacement: { replaced_account_id: null, replaced_by_account_id: null },
      status: 'open',
      type: 'account',
    },
    required: [
      'balances',
      'created_at',
      'currency',
      'entity_id',
      'informational_entity_id',
      'id',
      'interest_accrued',
      'interest_accrued_at',
      'name',
      'status',
      'type',
    ],
    title: 'Account',
    'x-tag': 'Accounts',
    'x-title-plural': 'Accounts',
  })
  .openapi('Account')

