const AccountNumberSchema = z
  .object({
    account_id: z
      .string()
      .openapi({ description: 'The identifier for the account this Account Number belongs to.' }),
    account_number: z.string().openapi({ description: 'The account number.' }),
    created_at: z.iso
      .datetime({ offset: true })
      .openapi({
        description:
          'The [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) time at which the Account Number was created.',
      }),
    id: z.string().openapi({ description: 'The Account Number identifier.' }),
    name: z.string().openapi({ description: 'The name you choose for the Account Number.' }),
    routing_number: z
      .string()
      .openapi({
        description: "The American Bankers' Association (ABA) Routing Transit Number (RTN).",
      }),
    status: z
      .enum(['active', 'disabled', 'canceled'])
      .openapi({
        description: 'This indicates if payments can be made to the Account Number.',
        'x-enum-descriptions': [
          'The account number is active.',
          'The account number is temporarily disabled.',
          'The account number is permanently disabled.',
        ],
      }),
    type: z
      .literal('account_number')
      .openapi({
        description:
          "A constant representing the object's type. For this resource it will always be `account_number`.",
      }),
  })
  .openapi({
    description:
      'Each account can have multiple account and routing numbers. We recommend that you use a set per vendor. This is similar to how you use different passwords for different websites. Account numbers can also be used to seamlessly reconcile inbound payments. Generating a unique account number per vendor ensures you always know the originator of an incoming payment.',
    example: {
      account_id: 'account_in71c4amph0vgo2qllky',
      account_number: '987654321',
      created_at: '2020-01-31T23:59:59Z',
      id: 'account_number_v18nkfqm6afpsrvy82b2',
      name: 'ACH',
      replacement: { replaced_account_number_id: null, replaced_by_account_number_id: null },
      routing_number: '101050001',
      status: 'active',
      type: 'account_number',
    },
    required: [
      'account_id',
      'account_number',
      'id',
      'created_at',
      'name',
      'routing_number',
      'status',
      'type',
    ],
    title: 'Account Number',
    'x-tag': 'Account Numbers',
    'x-title-plural': 'Account Numbers',
  })
  .openapi('AccountNumber')

