export const getRoutingNumbersRoute = createRoute({
  method: 'get',
  path: '/routing_numbers',
  summary: 'List Routing Numbers',
  description:
    'You can use this API to confirm if a routing number is valid, such as when a user is providing you with bank account details. Since routing numbers uniquely identify a bank, this will always return 0 or 1 entry. In Sandbox, the only valid routing number for this method is 110000000.',
  operationId: 'list_routing_numbers',
  request: {
    query: z.object({
      cursor: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'cursor',
            required: false,
            schema: { description: 'Return the page of entries after this one.', type: 'string' },
          },
          description: 'Return the page of entries after this one.',
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(0),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'limit',
            required: false,
            schema: {
              description:
                'Limit the size of the list that is returned. The default (and maximum) is 100 objects.',
              minimum: 0,
              type: 'integer',
            },
          },
          description:
            'Limit the size of the list that is returned. The default (and maximum) is 100 objects.',
        }),
      routing_number: z
        .string()
        .length(9)
        .openapi({
          param: {
            example: '021000021',
            in: 'query',
            name: 'routing_number',
            required: true,
            schema: {
              description: 'Filter financial institutions by routing number.',
              maxLength: 9,
              minLength: 9,
              type: 'string',
            },
          },
          description: 'Filter financial institutions by routing number.',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Routing Number List',
      content: { 'application/json': { schema: RoutingNumberListSchema } },
    },
    default: { description: 'Error', content: { 'application/json': { schema: ErrorSchema } } },
  },
})

